package app.metrolife;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.web.socket.*;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** R2 item 4: physical arrival ownership and presence/social use the same snapshot. */
class PresenceArrivalTests {
 @TempDir Path dir;GameService g;long now=1000000000;String token;LiveWire wire;
 @BeforeEach void setup()throws Exception{var mapper=new ObjectMapper();g=new GameService(new JsonStore(mapper,dir.resolve("save.json").toString()),new Content(mapper),mapper);g.time=()->now;token=create();}
 @AfterEach void close(){if(wire!=null)wire.close();}
 String create(){String t=g.guest(null,g.object()).token();ActivityFixture.setup(g,t,g.object().put("city","atl").put("neighborhood","midtown").put("aspiration","founder"));online(t);return t;}
 ObjectNode sim(String t){return g.sim(g.session(t,true));}
 void online(String t){g.community.online.put("public:"+sim(t).path("userId").asText(),now);}
 void arrive(String t,String loc){ObjectNode s=sim(t);s.put("loc",loc);s.remove("position");g.navigation.position(s);}
 double distance(JsonNode a,JsonNode b){return Math.hypot(a.path("x").asDouble()-b.path("x").asDouble(),a.path("z").asDouble()-b.path("z").asDouble());}
 void spaced(List<JsonNode> positions,String room){for(int i=0;i<positions.size();i++){JsonNode at=positions.get(i);assertEquals(room,at.path("room").asText(""));assertTrue(g.navigation.stand("atl",at.path("x").asDouble(),at.path("z").asDouble(),room));for(int j=0;j<i;j++)assertTrue(distance(at,positions.get(j))>=.84999,"Overlapping arrivals "+at+" and "+positions.get(j));}}
 @Test void eightNewPlayersAndPublicRoomEntriesGetFreeWalkableSpots(){List<String> people=new ArrayList<>();people.add(token);for(int i=0;i<7;i++)people.add(create());spaced(people.stream().map(t->(JsonNode)sim(t).path("position")).toList(),"");for(String t:people){arrive(t,"fox");g.door(t,g.object().put("loc","fox").put("enter",true));}spaced(people.stream().map(t->(JsonNode)sim(t).path("position")).toList(),"theatre:fox");}
 @Test void concurrentMapTripsAndVenueExitsDoNotMerge(){String second=create();for(String t:List.of(token,second)){g.travel(t,g.object().put("city","atl").put("loc","fox"));}now+=2000;for(String t:List.of(token,second))g.getSim(t);spaced(List.of(sim(token).path("position"),sim(second).path("position")),"");for(String t:List.of(token,second))g.door(t,g.object().put("loc","fox").put("enter",true));for(String t:List.of(token,second))g.door(t,g.object().put("enter",false));spaced(List.of(sim(token).path("position"),sim(second).path("position")),"");}
 @Test void offlineReturnDoesNotReclaimAnOccupiedPoint(){String second=create();ObjectNode s=sim(token),other=sim(second);ObjectNode old=s.withObject("position").deepCopy();g.community.online.remove("public:"+s.path("userId").asText());now+=13000;other.set("position",old.deepCopy());online(second);g.getSim(token);assertTrue(distance(s.path("position"),other.path("position"))>=.85);assertTrue(g.navigation.stand("atl",s.path("position").path("x").asDouble(),s.path("position").path("z").asDouble(),""));}
 @Test void publicEntryAvoidsNpcBodyAndReservedUsePoint(){g.players(token,"atl");ObjectNode npc=(ObjectNode)g.community.residents().path("public").elements().next();npc.put("city","atl").put("loc","fox").put("_phase","approach");JsonNode entry=g.navigation.layout("atl","theatre").path("exit");npc.putObject("position").put("city","atl").put("place","fox").put("room","theatre:fox").put("x",entry.path("x").asDouble()).put("z",entry.path("z").asDouble());npc.putObject("_roomSlot").put("id","reserved-entry-neighbour").put("x",entry.path("x").asDouble()-.9).put("z",entry.path("z").asDouble());arrive(token,"fox");g.door(token,g.object().put("loc","fox").put("enter",true));JsonNode at=sim(token).path("position");assertTrue(distance(at,npc.path("position"))>=.85);assertTrue(distance(at,npc.path("_roomSlot"))>=.85);}
 @Test void neighbourAvailabilityUsesExactRoomEffectivePoseAndBusyState(){String second=create();arrive(token,"fox");arrive(second,"fox");g.door(token,g.object().put("loc","fox").put("enter",true));assertFalse(g.community.near(sim(token),sim(second)));assertThrows(ApiException.class,()->g.social(token,g.object().put("targetId",sim(second).path("userId").asText()).put("kind","wave")));g.door(second,g.object().put("loc","fox").put("enter",true));assertTrue(g.community.near(sim(token),sim(second)));sim(second).put("busyUntil",now+1000);assertTrue(g.players(token,"atl").path("players").findValues("id").size()>0);assertTrue(g.community.player(sim(second),"public").path("socialBusy").asBoolean());assertThrows(ApiException.class,()->g.social(token,g.object().put("targetId",sim(second).path("userId").asText()).put("kind","wave")));now+=1000;g.community.preparePresence("public");assertFalse(g.community.player(sim(second),"public").path("socialBusy").asBoolean());assertTrue(g.social(token,g.object().put("targetId",sim(second).path("userId").asText()).put("kind","wave")).has("text"));}
 @Test void seatedNpcDistanceMatchesVisibleSlotAndAcceptedWaveHoldsThem(){g.players(token,"atl");ObjectNode npc=(ObjectNode)g.community.residents().path("public").elements().next();npc.put("city","atl").put("loc","fox").put("_phase","dwell");npc.putObject("position").put("city","atl").put("place","fox").put("room","theatre:fox").put("x",0).put("z",4);npc.putObject("activitySlot").put("id","seat-0-0").put("pose","Sit").put("x",-1.8).put("z",-.25);arrive(token,"fox");g.door(token,g.object().put("loc","fox").put("enter",true));sim(token).withObject("position").put("x",-1.8).put("z",1);assertTrue(g.community.near(sim(token),npc));assertTrue(g.social(token,g.object().put("targetId",npc.path("userId").asText()).put("kind","wave")).has("text"));assertEquals(now+5000,npc.path("_socialHoldUntil").asLong());}
 WebSocketSession socket(String id){WebSocketSession ws=mock(WebSocketSession.class);when(ws.getId()).thenReturn(id);when(ws.isOpen()).thenReturn(true);when(ws.getAttributes()).thenReturn(Map.of("token",token,"wid","public"));return ws;}
 @Test void closingLastSocketClearsPresenceButAnotherTabKeepsIt(){wire=new LiveWire(g);WebSocketSession one=socket("one"),two=socket("two");wire.afterConnectionEstablished(one);wire.afterConnectionEstablished(two);wire.afterConnectionClosed(one,CloseStatus.NORMAL);assertTrue(g.community.isOnline("public",sim(token).path("userId").asText()));wire.afterConnectionClosed(two,CloseStatus.NORMAL);assertFalse(g.community.isOnline("public",sim(token).path("userId").asText()));}
 @Test void websocketPositionSnapshotSettlesDueTravelBeforePublishing()throws Exception{wire=new LiveWire(g);List<String> frames=new CopyOnWriteArrayList<>();WebSocketSession ws=socket("trip");doAnswer(i->{frames.add(((TextMessage)i.getArgument(0)).getPayload());return null;}).when(ws).sendMessage(any());wire.afterConnectionEstablished(ws);g.travel(token,g.object().put("city","atl").put("loc","ponce"));now+=2000;wire.motionTick();long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(frames.stream().noneMatch(f->f.contains("\"type\":\"positions\""))&&System.nanoTime()<deadline)Thread.sleep(5);JsonNode frame=frames.stream().map(f->{try{return g.mapper.readTree(f);}catch(Exception e){throw new RuntimeException(e);}}).filter(f->f.path("type").asText().equals("positions")).findFirst().orElseThrow();JsonNode mine=null;for(JsonNode row:frame.path("players"))if(row.path("id").asText().equals(sim(token).path("userId").asText()))mine=row;assertNotNull(mine);assertEquals("ponce",mine.path("loc").asText());assertEquals("ponce",mine.path("position").path("place").asText());assertTrue(mine.path("position").path("room").isNull());assertFalse(mine.path("socialBusy").asBoolean());assertTrue(distance(mine.path("position"),g.navigation.door(sim(token),"ponce"))<3);}
}
